mapper.select:
SELECT CONFIG_ID, PROFILE, PROP_KEY, PROP_VALUE,
       DATA_TYPE, EDITABLE_YN, RESTART_YN, DESCRIPTION, USE_YN
FROM   SYS_CONFIG
WHERE  PROFILE  = #{profile}
AND    PROP_KEY = #{propKey}
AND    USE_YN   = 'Y'

mapper.update:
UPDATE SYS_CONFIG
SET    PROP_VALUE = #{propValue},
       MOD_DT    = CURRENT_TIMESTAMP
WHERE  PROFILE  = #{profile}
AND    PROP_KEY = #{propKey}
AND    EDITABLE_YN = 'Y'
